vector<int> countingSort(const vector<int>& a) {
    if (a.empty()) return a;
    int M = *max_element(a.begin(), a.end());
    vector<int> count(M + 1, 0);
    for (int v : a) count[v]++;                  // tally
    vector<int> out;
    for (int v = 0; v <= M; ++v)
        out.insert(out.end(), count[v], v);      // expand in sorted order
    return out;
}

def counting_sort(a):
    if not a: return a
    M = max(a)
    count = [0] * (M + 1)
    for v in a:
        count[v] += 1
    out = []
    for v in range(M + 1):
        out.extend([v] * count[v])
    return out

class Solution {
public:
    vector<int> sortArray(vector<int>& a) {
        if (a.empty()) return a;
        int lo = *min_element(a.begin(), a.end());
        int hi = *max_element(a.begin(), a.end());
        vector<int> cnt(hi - lo + 1, 0);
        for (int x : a) cnt[x - lo]++;
        int idx = 0;
        for (int v = 0; v < (int)cnt.size(); v++)
            while (cnt[v]--) a[idx++] = v + lo;
        return a;
    }
};

class Solution:
    def sortArray(self, a: list[int]) -> list[int]:
        if not a:
            return a
        lo, hi = min(a), max(a)
        cnt = [0] * (hi - lo + 1)
        for x in a:
            cnt[x - lo] += 1
        out = []
        for v, c in enumerate(cnt):
            out.extend([v + lo] * c)
        return out

class Solution {
public:
    void sortColors(vector<int>& a) {
        int low = 0, mid = 0, high = a.size() - 1;
        while (mid <= high) {
            if (a[mid] == 0) swap(a[low++], a[mid++]);
            else if (a[mid] == 1) mid++;
            else swap(a[mid], a[high--]);
        }
    }
};

class Solution:
    def sortColors(self, a: list[int]) -> None:
        low, mid, high = 0, 0, len(a) - 1
        while mid <= high:
            if a[mid] == 0:
                a[low], a[mid] = a[mid], a[low]
                low += 1
                mid += 1
            elif a[mid] == 1:
                mid += 1
            else:
                a[mid], a[high] = a[high], a[mid]
                high -= 1

class Solution {
public:
    vector<int> relativeSortArray(vector<int>& a, vector<int>& b) {
        vector<int> cnt(1001, 0);
        for (int x : a) cnt[x]++;
        vector<int> res;
        for (int x : b) while (cnt[x]--) res.push_back(x);
        for (int v = 0; v <= 1000; v++) while (cnt[v]-- > 0) res.push_back(v);
        return res;
    }
};

class Solution:
    def relativeSortArray(self, arr1: list[int], arr2: list[int]) -> list[int]:
        cnt = [0] * 1001
        for x in arr1:
            cnt[x] += 1
        res = []
        for x in arr2:
            res.extend([x] * cnt[x])
            cnt[x] = 0
        for v in range(1001):
            res.extend([v] * cnt[v])
        return res

class Solution {
public:
    int maximumGap(vector<int>& a) {
        int n = a.size();
        if (n < 2) return 0;
        int lo = *min_element(a.begin(), a.end());
        int hi = *max_element(a.begin(), a.end());
        if (lo == hi) return 0;
        int bsize = max(1, (hi - lo) / (n - 1));
        int cnt = (hi - lo) / bsize + 1;
        vector<int> bmin(cnt, INT_MAX), bmax(cnt, INT_MIN);
        for (int x : a) { int b = (x - lo) / bsize; bmin[b] = min(bmin[b], x); bmax[b] = max(bmax[b], x); }
        int gap = 0, prev = lo;
        for (int b = 0; b < cnt; b++) {
            if (bmin[b] == INT_MAX) continue;
            gap = max(gap, bmin[b] - prev);
            prev = bmax[b];
        }
        return gap;
    }
};

class Solution:
    def maximumGap(self, a: list[int]) -> int:
        n = len(a)
        if n < 2:
            return 0
        lo, hi = min(a), max(a)
        if lo == hi:
            return 0
        bsize = max(1, (hi - lo) // (n - 1))
        cnt = (hi - lo) // bsize + 1
        bmin = [float('inf')] * cnt
        bmax = [float('-inf')] * cnt
        for x in a:
            b = (x - lo) // bsize
            bmin[b] = min(bmin[b], x)
            bmax[b] = max(bmax[b], x)
        gap, prev = 0, lo
        for b in range(cnt):
            if bmin[b] == float('inf'):
                continue
            gap = max(gap, bmin[b] - prev)
            prev = bmax[b]
        return gap

class Solution {
public:
    int hIndex(vector<int>& c) {
        int n = c.size();
        vector<int> bucket(n + 1, 0);
        for (int x : c) bucket[min(x, n)]++;
        int total = 0;
        for (int i = n; i >= 0; i--) {
            total += bucket[i];
            if (total >= i) return i;
        }
        return 0;
    }
};

class Solution:
    def hIndex(self, citations: list[int]) -> int:
        n = len(citations)
        bucket = [0] * (n + 1)
        for x in citations:
            bucket[min(x, n)] += 1
        total = 0
        for i in range(n, -1, -1):
            total += bucket[i]
            if total >= i:
                return i
        return 0
